<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,nextTick} from 'vue'
import {ElMessage,ElMessageBox} from 'element-plus'
import {DataAnalysis,ChatLineSquare,TrendCharts,Collection,Document,User,SwitchButton,Setting,Search,ArrowRight,Refresh} from '@element-plus/icons-vue'
import * as echarts from 'echarts'
import {marked} from 'marked'
import DOMPurify from 'dompurify'
type Row=Record<string,any>
const me=ref<Row|null>(null), ready=ref(false), view=ref('dashboard'),loading=ref(false)
const login=ref({username:'',password:''}),loginBusy=ref(false)
const dashboard=ref<Row>({}),metrics=ref<Row[]>([]),history=ref<Row[]>([]),users=ref<Row[]>([]),audit=ref<Row[]>([])
const query=ref(''),job=ref<Row|null>(null),submitting=ref(false),search=ref(''),domain=ref('全部'),selected=ref<Row|null>(null)
const metricValue=ref<Row|null>(null),period=ref('2026-08'),calculating=ref(false),drawer=ref(false)
const accountDialog=ref(false),passwordDialog=ref(false),passwordForm=ref({old_password:'',new_password:''})
const accountForm=ref<Row>({username:'',display_name:'',role:'sales',region:'华东',password:''})
const editId=ref<number|null>(null),usage=ref<Row>({}),chartNode=ref<HTMLElement>(),chart2Node=ref<HTMLElement>()
let chart:echarts.ECharts|undefined,chart2:echarts.ECharts|undefined,poll:ReturnType<typeof setTimeout>|undefined,requestVersion=0
const routes=[{id:'dashboard',name:'经营总览',icon:DataAnalysis},{id:'query',name:'智能问数',icon:ChatLineSquare},{id:'analysis',name:'经营分析',icon:TrendCharts},{id:'metrics',name:'指标中心',icon:Collection},{id:'reports',name:'个人报告',icon:Document},{id:'accounts',name:'账户管理',icon:User},{id:'audit',name:'审计记录',icon:Setting}]
const menus=computed(()=>routes.filter(r=>r.id==='audit'?me.value?.role==='admin':me.value?.menus?.includes(r.id)))
const title=computed(()=>routes.find(r=>r.id===view.value)?.name||'经营工作台')
const roles=[['admin','系统管理员'],['executive','经营负责人'],['finance','财务分析师'],['sales','销售经理'],['production','生产主管'],['warehouse','仓储主管']]
const filteredMetrics=computed(()=>metrics.value.filter(m=>(domain.value==='全部'||m.domain===domain.value)&&`${m.name}${m.code}${m.definition}`.includes(search.value)))
const statusLabels:Row={queued:'等待执行',running:'分析中',completed:'已完成',partial:'部分完成',failed:'未完成',needs_clarification:'需补充信息'}
const fmt=(value:any,digits=2)=>value==null?'—':Number(value).toLocaleString('zh-CN',{maximumFractionDigits:digits})
const money=(value:any)=>value==null?'—':fmt(Number(value)/10000)
const dateLabel=(value:any)=>value?new Date(typeof value==='number'?value*1000:value).toLocaleString('zh-CN'):'—'
async function api(path:string,options:RequestInit={}):Promise<any>{
 const res=await fetch(path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}})
 const data=await res.json().catch(()=>({}))
 if(res.status===401){me.value=null;stopPoll();throw new Error('请登录后继续')}
 if(!res.ok)throw new Error(typeof data.detail==='string'?data.detail:'操作未完成，请检查输入')
 return data
}
function failure(error:unknown){ElMessage.error(error instanceof Error?error.message:'操作失败')}
async function signIn(){loginBusy.value=true;try{await api('/api/login',{method:'POST',body:JSON.stringify(login.value)});me.value=await api('/api/me');login.value.password='';await navigate('dashboard')}catch(e){failure(e)}finally{loginBusy.value=false}}
async function signOut(){try{await api('/api/logout',{method:'POST'});me.value=null;job.value=null;stopPoll()}catch(e){failure(e)}}
function stopPoll(){if(poll)clearTimeout(poll);poll=undefined}
function disposeCharts(){chart?.dispose();chart2?.dispose();chart=chart2=undefined}
async function navigate(target:string){
 if(!menus.value.some(m=>m.id===target))target='dashboard'
 view.value=target;location.hash=target;stopPoll();submitting.value=false;disposeCharts();const version=++requestVersion;loading.value=true
 try{
   if(target==='dashboard'){const d=await api('/api/dashboard');if(version!==requestVersion)return;dashboard.value=d;await nextTick();renderCharts()}
   if(target==='metrics'){metrics.value=(await api('/api/metrics')).items}
   if(target==='reports')history.value=await api('/api/history')
   if(target==='accounts')users.value=(await api('/api/admin/users')).users
   if(target==='audit')audit.value=(await api('/api/admin/audit')).items
   usage.value=await api('/api/usage')
 }catch(e){failure(e)}finally{if(version===requestVersion)loading.value=false}
}
const cards=computed(()=>{
 const k=dashboard.value.kpi||{}
 if(dashboard.value.view==='production')return [['实际产出',fmt(k.output_meters,0),'米','生产累计'],['生产良品率',fmt(k.yield_pct),'%','按总量加权'],['计划达成率',fmt(k.plan_pct),'%','实际 / 计划'],['生产批次',fmt(k.batches,0),'批','已采集批次']]
 if(dashboard.value.view==='warehouse')return [['期末库存',fmt(k.stock_meters,0),'米','最新快照'],['库存金额',money(k.stock_value),'万元','成本口径'],['长库龄数量',fmt(k.aged_meters,0),'米','库龄超过90天'],['长库龄占比',fmt(k.aged_pct),'%','数量口径']]
 return [['确认销售收入',money(k.revenue),'万元','按交付日期'],['已交付订单',fmt(k.orders,0),'笔','已完成订单'],['交付数量',fmt(k.meters,0),'米','面料总量'],...(me.value?.role==='sales'?[['期末库存',fmt(dashboard.value.inventory?.stock,0),'米','授权区域']]:[['销售毛利',money(k.gross_profit),'万元','收入减实际成本']])]
})
function renderCharts(){
 if(!chartNode.value)return
 const rows=dashboard.value.trend||[];chart=echarts.init(chartNode.value)
 if(rows.length)chart.setOption({color:['#235fea','#21a68b'],tooltip:{trigger:'axis'},legend:{bottom:0},grid:{left:62,right:24,top:25,bottom:62},xAxis:{type:'category',data:rows.map((r:Row)=>r.month),axisLine:{lineStyle:{color:'#d6dfec'}}},yAxis:{type:'value',name:'万元',splitLine:{lineStyle:{color:'#edf1f7'}}},series:[{name:'收入',type:'line',smooth:true,symbolSize:7,data:rows.map((r:Row)=>Number(r.revenue)/10000),areaStyle:{opacity:.07}},...(me.value?.role==='sales'?[]:[{name:'毛利',type:'line',smooth:true,data:rows.map((r:Row)=>Number(r.gross_profit)/10000)}])]})
 else chart.setOption({title:{text:dashboard.value.view==='production'?'生产指标概览':'库龄结构',left:'center',textStyle:{fontSize:14}},tooltip:{trigger:'item'},series:[{type:'pie',radius:['45%','67%'],data:dashboard.value.view==='production'?[{name:'合格产量',value:Number(dashboard.value.kpi.output_meters)*Number(dashboard.value.kpi.yield_pct)/100},{name:'不良产量',value:Number(dashboard.value.kpi.output_meters)*(100-Number(dashboard.value.kpi.yield_pct))/100}]:[{name:'90天以内',value:Number(dashboard.value.kpi.stock_meters)-Number(dashboard.value.kpi.aged_meters)},{name:'90天以上',value:Number(dashboard.value.kpi.aged_meters)}]}],color:['#235fea','#edb052']})
 if(chart2Node.value){chart2=echarts.init(chart2Node.value);const products=[...(dashboard.value.products||[])].reverse();chart2.setOption({color:['#4778e9'],tooltip:{trigger:'axis'},grid:{left:120,right:25,top:20,bottom:35},xAxis:{type:'value',name:'万元'},yAxis:{type:'category',data:products.map((r:Row)=>r.product_name)},series:[{type:'bar',barMaxWidth:16,data:products.map((r:Row)=>Number(r.revenue)/10000),itemStyle:{borderRadius:[0,4,4,0]}}]})}
}
function resize(){chart?.resize();chart2?.resize()}
async function submit(){if(!query.value.trim())return;submitting.value=true;job.value=null;try{const r=await api('/api/jobs',{method:'POST',body:JSON.stringify({question:query.value,mode:'auto'})});await pollJob(r.id)}catch(e){failure(e);submitting.value=false}}
async function pollJob(id:string){try{job.value=await api('/api/jobs/'+id);if(['queued','running'].includes(job.value!.status)){poll=setTimeout(()=>pollJob(id),1500)}else{submitting.value=false;usage.value=await api('/api/usage')}}catch(e){submitting.value=false;failure(e)}}
async function openReport(row:Row){await navigate('query');query.value=row.question;submitting.value=true;await pollJob(row.id)}
const renderedReport=computed(()=>DOMPurify.sanitize(marked.parse(String(job.value?.report||''),{async:false}) as string))
function hashChanged(){const target=location.hash.slice(1);if(me.value&&target!==view.value)void navigate(target)}
function selectMetric(m:Row){selected.value=m;metricValue.value=null;drawer.value=true}
async function calculate(){if(!selected.value)return;calculating.value=true;try{const [y,m]=period.value.split('-').map(Number);const next=new Date(y,m,1);const end=`${next.getFullYear()}-${String(next.getMonth()+1).padStart(2,'0')}-01`;metricValue.value=await api(`/api/metrics/${selected.value.code}/calculate`,{method:'POST',body:JSON.stringify({start:period.value+'-01',end})})}catch(e){failure(e)}finally{calculating.value=false}}
function editAccount(row?:Row){editId.value=row?.user_id||null;accountForm.value=row?{...row,password:''}:{username:'',display_name:'',role:'sales',region:'华东',password:''};accountDialog.value=true}
async function saveAccount(){try{const payload={...accountForm.value};if(!payload.password)delete payload.password;await api('/api/admin/users'+(editId.value?'/'+editId.value:''),{method:editId.value?'PATCH':'POST',body:JSON.stringify(payload)});accountDialog.value=false;ElMessage.success('账户已保存');await navigate('accounts')}catch(e){failure(e)}}
async function toggleAccount(row:Row){try{await ElMessageBox.confirm(`确认${row.active?'停用':'启用'}账户「${row.display_name}」？`,'账户状态');await api('/api/admin/users/'+row.user_id,{method:'PATCH',body:JSON.stringify({active:!row.active})});await navigate('accounts')}catch(e){if(e!=='cancel')failure(e)}}
async function changePassword(){try{await api('/api/password',{method:'POST',body:JSON.stringify(passwordForm.value)});passwordDialog.value=false;passwordForm.value={old_password:'',new_password:''};me.value=null;ElMessage.success('密码已修改，请重新登录')}catch(e){failure(e)}}
onMounted(async()=>{try{me.value=await api('/api/me');await navigate(location.hash.slice(1)||'dashboard')}catch{}finally{ready.value=true}window.addEventListener('resize',resize);window.addEventListener('hashchange',hashChanged)})
onBeforeUnmount(()=>{stopPoll();disposeCharts();window.removeEventListener('resize',resize);window.removeEventListener('hashchange',hashChanged)})
</script>

<template>
 <div v-if="!ready" class="boot">正在载入经营工作台…</div>
 <div v-else-if="!me" class="login-shell">
  <section class="login-story"><div class="brand"><b>织</b><span>织见<span class="brand-sub">经营智能分析平台</span></span></div><div class="story-copy"><p class="eyebrow">BUSINESS INTELLIGENCE</p><h1>从业务问题<br>到有依据的决策。</h1><p>连接销售、生产、采购与库存数据，<br>用统一的指标语言理解经营。</p></div><div class="weave" aria-hidden="true"></div><footer>东莞德永佳纺织制衣有限公司</footer></section>
  <section class="login-form"><div class="login-box"><p class="eyebrow">WELCOME BACK</p><h2>登录经营工作台</h2><p class="muted">使用企业账户访问你的业务范围</p><el-form @submit.prevent="signIn" label-position="top"><el-form-item label="账户"><el-input v-model="login.username" autocomplete="username" placeholder="请输入账户名" size="large"/></el-form-item><el-form-item label="密码"><el-input v-model="login.password" type="password" show-password autocomplete="current-password" placeholder="请输入密码" size="large"/></el-form-item><el-button native-type="submit" type="primary" size="large" :loading="loginBusy" class="wide">登录</el-button></el-form><p class="login-help">账户开通与权限调整请联系系统管理员</p></div><footer class="simulation">项目模拟环境 · 公司名称、业务数据与权限配置仅用于项目验证</footer></section>
 </div>
 <div v-else class="shell">
  <aside class="sidebar"><div class="brand"><b>织</b><span>织见<span class="brand-sub">德永佳经营分析</span></span></div><div class="nav-label">工作空间</div><nav><button v-for="r in menus" :key="r.id" :class="{active:view===r.id}" @click="navigate(r.id)"><el-icon><component :is="r.icon"/></el-icon>{{r.name}}<span v-if="r.id==='query'" class="ai-badge">AI</span></button></nav><div class="sidebar-bottom"><div class="avatar">{{me.name?.slice(0,1)}}</div><div><strong>{{me.name}}</strong><small>{{me.role_name}}</small></div><el-button text @click="signOut" aria-label="退出登录"><el-icon><SwitchButton/></el-icon></el-button></div></aside>
  <div class="workspace"><header class="topbar"><div class="breadcrumb">经营工作台 <span>/</span> <strong>{{title}}</strong></div><div class="top-actions"><span class="scope-dot"></span><span>{{me.region||'全公司'}}数据范围</span><el-button text @click="passwordDialog=true" :icon="Setting">账户设置</el-button></div></header>
   <main v-loading="loading"><div class="page-heading"><div><p class="eyebrow">{{view==='dashboard'?'MANAGEMENT OVERVIEW':'WORKSPACE / '+view.toUpperCase()}}</p><h1>{{title}}</h1><p class="muted">{{view==='dashboard'?'围绕收入、交付与库存，了解当前经营表现。':view==='metrics'?'统一定义、计算公式与时间口径，让数据可理解、可核对。':'每个业务结论，都从可核对的数据出发。'}}</p></div><span class="environment-tag">模拟业务环境</span></div>
    <template v-if="view==='dashboard'"><div class="period-bar"><span>统计期间：2026年3月—8月</span><span>金额为不含税人民币 · {{me.region||'全部授权区域'}}</span><el-button text :icon="Refresh" @click="navigate('dashboard')">刷新</el-button></div><div class="kpi-grid"><article v-for="(c,i) in cards" :key="c[0]" class="kpi"><div class="kpi-label">{{c[0]}}<span>{{String(i+1).padStart(2,'0')}}</span></div><div class="kpi-number">{{c[1]}}<small>{{c[2]}}</small></div><p>{{c[3]}}</p></article></div><div class="chart-grid"><section class="panel"><div class="panel-head"><h3>{{dashboard.trend?'收入与毛利趋势':'业务结构'}}</h3><span>当前授权范围</span></div><div ref="chartNode" class="chart"></div></section><section v-if="dashboard.products" class="panel"><div class="panel-head"><h3>产品收入贡献</h3><span>按交付日期</span></div><div ref="chart2Node" class="chart"></div></section><section v-else class="panel insight-card"><p class="eyebrow">ASK YOUR DATA</p><h2>进一步理解<br>变化背后的业务。</h2><p>查看指标口径，或直接提出生产、库存相关问题。</p><el-button type="primary" @click="navigate('query')">开始问数 <el-icon><ArrowRight/></el-icon></el-button></section></div><section class="panel entry-card"><div><h3>从一个具体问题开始</h3><p class="muted">例如：2026年8月各客户的确认销售收入是多少？</p></div><el-button type="primary" plain @click="navigate('query')">进入智能问数</el-button></section></template>
    <template v-if="view==='query'||view==='analysis'"><section class="panel question-panel"><div class="panel-head"><h3>描述你的业务问题</h3><el-tag type="info" effect="plain">自动理解与分析</el-tag></div><el-input v-model="query" type="textarea" :rows="4" maxlength="1200" show-word-limit placeholder="请写明指标、期间和需要比较的维度，例如：分析2026年7—8月的销售毛利和期间费用变化。" @keydown.ctrl.enter="submit"/><div class="question-footer"><span>每次提交为独立问题；结果可能复用最近120秒的同权限缓存。</span><el-button type="primary" :loading="submitting" :disabled="!query.trim()" @click="submit">提交问题 <el-icon><ArrowRight/></el-icon></el-button></div><div class="suggestions"><button v-for="q in ['2026年8月营业收入是多少？','最新库存中90天以上库龄占比是多少？','2026年8月生产良品率是多少？']" @click="query=q">{{q}}</button></div></section>
     <section v-if="job" class="panel result-panel"><div class="panel-head"><h3>{{job.status==='needs_clarification'?'需要补充的信息':'分析结果'}}</h3><el-tag :type="job.status==='failed'?'danger':job.status==='completed'?'success':'info'">{{statusLabels[job.status]||job.status}}</el-tag></div><el-alert v-if="job.error" :title="job.error" type="error" :closable="false"/><p v-if="job.cache_hit" class="muted">本次复用近期相同权限下的查询结果。</p><div v-if="job.report" class="report-text" v-html="renderedReport"></div><el-collapse v-if="job.events?.length"><el-collapse-item title="查看处理进度" name="progress"><el-timeline><el-timeline-item v-for="(event,i) in job.events" :key="i" :timestamp="dateLabel(event.time)">{{event.message}}</el-timeline-item></el-timeline></el-collapse-item></el-collapse><article v-for="result in job.results||[]" :key="result.step.id" class="step-result"><h4>{{result.step.id}}. {{result.step.title}}</h4><el-alert v-if="!result.success" :title="result.error" type="warning" :closable="false"/><el-table v-else :data="result.rows" stripe max-height="350"><el-table-column v-for="column in result.columns" :key="column" :prop="column" :label="column" min-width="150" show-overflow-tooltip/></el-table><el-collapse v-if="me.role==='admin'&&result.sql"><el-collapse-item title="管理员执行诊断"><pre>{{result.sql}}</pre><p>上下文：{{result.retrieval?.strategy}} · {{result.retrieval?.retriever||'直接注入'}}</p></el-collapse-item></el-collapse></article><a v-if="job.report&&job.status!=='needs_clarification'" :href="'/api/jobs/'+job.id+'/report'" class="download">下载分析报告</a></section><div v-else class="query-empty"><el-icon><ChatLineSquare/></el-icon><h3>先理解问题，再查询数据</h3><p>复杂分析会拆解为有依赖关系的查询步骤，最后汇总证据。</p></div></template>
    <template v-if="view==='metrics'"><section class="panel"><div class="toolbar"><el-input v-model="search" placeholder="搜索指标名称、编码或定义" :prefix-icon="Search" clearable/><el-select v-model="domain"><el-option v-for="d in ['全部','销售','财务','生产','采购','库存']" :key="d" :value="d" :label="d"/></el-select><span class="muted">{{filteredMetrics.length}} 个指标</span></div><el-table :data="filteredMetrics" @row-click="selectMetric" class="clickable"><el-table-column prop="code" label="指标编码" width="115"/><el-table-column prop="name" label="指标名称" min-width="190"/><el-table-column prop="domain" label="业务领域" width="110"/><el-table-column prop="unit" label="单位" width="100"/><el-table-column prop="owner" label="口径负责人" min-width="150"/><el-table-column label="权限" width="120"><template #default="{row}"><el-tag :type="row.visible?'success':'info'" effect="plain">{{row.visible?'可计算':'仅目录'}}</el-tag></template></el-table-column><el-table-column prop="version" label="版本" width="90"/></el-table></section></template>
    <template v-if="view==='reports'"><section class="panel"><div class="panel-head"><h3>我的查询与分析</h3><span>近期24小时 · 当前权限范围</span></div><el-empty v-if="!history.length" description="还没有分析记录"/><div v-for="item in history" :key="item.id" class="report-row"><el-icon><Document/></el-icon><div><strong>{{item.question}}</strong><p>{{dateLabel(item.created_at)}} · {{item.mode==='analysis'?'多步分析':'业务问数'}}</p></div><el-tag type="info">{{statusLabels[item.status]||item.status}}</el-tag><el-button text type="primary" @click="openReport(item)">查看</el-button></div></section></template>
    <template v-if="view==='accounts'"><section class="panel"><div class="panel-head"><div><h3>企业账户</h3><p class="muted">岗位决定功能和字段权限，区域进一步限制数据范围。</p></div><el-button type="primary" @click="editAccount()">创建账户</el-button></div><el-table :data="users"><el-table-column prop="display_name" label="姓名 / 账户名称" min-width="150"/><el-table-column prop="username" label="登录名" min-width="140"/><el-table-column label="岗位" min-width="130"><template #default="{row}">{{roles.find(r=>r[0]===row.role)?.[1]}}</template></el-table-column><el-table-column label="区域" width="100"><template #default="{row}">{{row.region||'全部'}}</template></el-table-column><el-table-column label="状态" width="100"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="170"><template #default="{row}"><el-button text @click="editAccount(row)">编辑</el-button><el-button text :disabled="row.username===me.user" @click="toggleAccount(row)">{{row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></section></template>
    <template v-if="view==='audit'"><section class="panel"><div class="panel-head"><h3>最近100条审计事件</h3><span>仅管理员可见</span></div><el-table :data="audit"><el-table-column prop="occurred_at" label="时间" min-width="180"/><el-table-column prop="username" label="账户" width="130"/><el-table-column prop="action" label="操作" width="160"/><el-table-column prop="detail" label="事件详情" min-width="400" show-overflow-tooltip/></el-table></section></template>
   </main><footer class="workspace-footer"><span>东莞德永佳纺织制衣有限公司 · 项目模拟配置</span><span v-if="usage.tokens!=null">今日模型用量 {{fmt(usage.tokens,0)}} / {{fmt(usage.limit,0)}} tokens</span></footer>
  </div>
 </div>
 <el-drawer v-model="drawer" :title="selected?.name" size="min(580px,95vw)"><template v-if="selected"><div class="metric-tags"><el-tag>{{selected.code}}</el-tag><el-tag type="info">{{selected.domain}}</el-tag><el-tag type="success">V{{selected.version}}</el-tag></div><h4>业务定义</h4><p>{{selected.definition}}</p><h4>计算公式</h4><div class="formula">{{selected.formula}}</div><el-descriptions :column="1" border><el-descriptions-item label="单位">{{selected.unit}}</el-descriptions-item><el-descriptions-item label="时间字段">{{selected.time_field||'参见组成指标'}}</el-descriptions-item><el-descriptions-item label="负责人">{{selected.owner}}</el-descriptions-item><el-descriptions-item label="维度">{{selected.dimensions?.join('、')||'—'}}</el-descriptions-item><el-descriptions-item label="适用范围">{{selected.scope}}</el-descriptions-item></el-descriptions><h4>口径说明</h4><ul><li v-for="c in selected.caveats||[]" :key="c">{{c}}</li></ul><div class="metric-calc"><h4>按期间核对指标</h4><el-date-picker v-model="period" type="month" value-format="YYYY-MM" :clearable="false"/><el-button type="primary" :disabled="!selected.visible" :loading="calculating" @click="calculate">计算</el-button><div v-if="metricValue" class="calculated">{{fmt(metricValue.value)}} <small>{{metricValue.unit}}</small></div><p v-if="!selected.visible" class="muted">当前岗位没有此指标的数据权限。</p></div></template></el-drawer>
 <el-dialog v-model="accountDialog" :title="editId?'编辑账户':'创建账户'" width="min(500px,94vw)"><el-form label-position="top"><el-form-item label="登录名"><el-input v-model="accountForm.username" :disabled="!!editId"/></el-form-item><el-form-item label="账户名称"><el-input v-model="accountForm.display_name"/></el-form-item><el-form-item label="岗位"><el-select v-model="accountForm.role"><el-option v-for="r in roles" :key="r[0]" :value="r[0]" :label="r[1]"/></el-select></el-form-item><el-form-item label="区域"><el-select v-model="accountForm.region" clearable><el-option v-for="r in ['华东','华南','华北']" :key="r" :value="r" :label="r"/></el-select></el-form-item><el-form-item :label="editId?'重置密码（留空保留）':'初始密码'"><el-input v-model="accountForm.password" type="password" show-password/></el-form-item></el-form><template #footer><el-button @click="accountDialog=false">取消</el-button><el-button type="primary" @click="saveAccount">保存</el-button></template></el-dialog>
 <el-dialog v-model="passwordDialog" title="修改密码" width="min(460px,94vw)"><el-form label-position="top"><el-form-item label="原密码"><el-input v-model="passwordForm.old_password" type="password" show-password/></el-form-item><el-form-item label="新密码（至少10位）"><el-input v-model="passwordForm.new_password" type="password" show-password/></el-form-item></el-form><template #footer><el-button type="primary" @click="changePassword">保存并重新登录</el-button></template></el-dialog>
</template>
